steps.script:
GameState.state["factions"]["2"].merge({"detachment": "Runt Swarm"}, true)
StratagemManager.load_faction_stratagems_for_player(2)
var u = GameState.state.units
var trukk = u["U_TRUKK_A"]
trukk["owner"] = 1
var tp = trukk.models[0].position
var cg = u["U_CUSTODIAN_GUARD_C"]
cg["embarked_in"] = "U_TRUKK_A"
for m in cg.models:
	m["position"] = null
if not trukk.has("transport_data"):
	trukk["transport_data"] = {}
trukk.transport_data["embarked_units"] = ["U_CUSTODIAN_GUARD_C"]
var i := 0
for m in u["U_GRETCHIN_C"].models:
	if m.get("alive", true):
		m["position"] = {"x": float(tp.x) + (-4.0 + i * 1.2) * 40.0, "y": float(tp.y) - 9.0 * 40.0}
		i += 1
PhaseManager.get_current_phase_instance().game_state_snapshot = GameState.create_snapshot()
tree.current_scene._recreate_unit_visuals()
return StratagemManager.get_stratagem("faction_ork_runt_swarm_scarper").get("implemented", false)

var p = PhaseManager.get_current_phase_instance()
var payload: Dictionary = p._ork11e_greedy_disembark_payload("U_CUSTODIAN_GUARD_C", ["U_CUSTODIAN_GUARD_C"], "U_TRUKK_A", 1)
if payload.is_empty():
	return "no set-up"
var r = p.execute_action({"type": "CONFIRM_DISEMBARK", "actor_unit_id": "U_CUSTODIAN_GUARD_C", "player": 1, "payload": payload})
return r.get("success", false)
